import Foundation
import CryptoKit

// Circuit Breaker States
enum CircuitState {
    case closed
    case open
    case halfOpen
}

// Circuit Breaker for cryptographic operations
class CryptoCircuitBreaker {
    private var state: CircuitState = .closed
    private var failureCount: Int = 0
    private var lastFailureTime: Date?
    private let failureThreshold: Int = 5
    private let resetTimeout: TimeInterval = 30.0
    private let queue = DispatchQueue(label: "circuit.breaker.queue")

    func canExecute() -> Bool {
        return queue.sync {
            switch state {
            case .closed:
                return true
            case .open:
                if let lastFailure = lastFailureTime,
                   Date().timeIntervalSince(lastFailure) > resetTimeout {
                    state = .halfOpen
                    return true
                }
                return false
            case .halfOpen:
                return true
            }
        }
    }

    func recordSuccess() {
        queue.sync {
            failureCount = 0
            state = .closed
        }
    }

    func recordFailure() {
        queue.sync {
            failureCount += 1
            lastFailureTime = Date()
            if failureCount >= failureThreshold {
                state = .open
            }
        }
    }
}

// Token validation service
class TokenValidationService {
    private let circuitBreaker = CryptoCircuitBreaker()
    private let hmacKey: SymmetricKey

    init(secret: String) {
        self.hmacKey = SymmetricKey(data: Data(secret.utf8))
    }

    // Generates a state-changing action token
    func generateActionToken(sessionId: String, action: String, timestamp: UInt64) -> String {
        let payload = "\(sessionId):\(action):\(timestamp)"
        let hmac = HMAC<SHA256>.authenticationCode(for: Data(payload.utf8), using: hmacKey)
        return Data(hmac).base64EncodedString()
    }

    // Validates the action token with circuit breaker protection
    func validateActionToken(token: String, sessionId: String, action: String, timestamp: UInt64) -> Bool {
        guard circuitBreaker.canExecute() else {
            // Circuit is open - fail closed to maintain security
            return false
        }

        let payload = "\(sessionId):\(action):\(timestamp)"
        let expectedHMAC = HMAC<SHA256>.authenticationCode(for: Data(payload.utf8), using: hmacKey)
        let expectedToken = Data(expectedHMAC).base64EncodedString()

        guard let tokenData = Data(base64Encoded: token),
              let expectedData = Data(base64Encoded: expectedToken) else {
            circuitBreaker.recordFailure()
            return false
        }

        // Constant-time comparison
        let isValid = tokenData.count == expectedData.count &&
            zip(tokenData, expectedData).reduce(0) { $0 | ($1.0 ^ $1.1) } == 0

        if isValid {
            circuitBreaker.recordSuccess()
        } else {
            circuitBreaker.recordFailure()
        }

        return isValid
    }
}

// Request handler for state-changing operations
class SecureActionHandler {
    private let tokenService: TokenValidationService
    private let tokenExpiry: UInt64 = 300 // 5 minutes

    init(secret: String) {
        self.tokenService = TokenValidationService(secret: secret)
    }

    struct ActionRequest {
        let sessionId: String
        let action: String
        let csrfToken: String
        let timestamp: UInt64
    }

    struct ActionResponse {
        let success: Bool
        let message: String
    }

    func handleStateChange(request: ActionRequest) -> ActionResponse {
        let currentTime = UInt64(Date().timeIntervalSince1970)

        // Check token expiry
        guard currentTime - request.timestamp <= tokenExpiry else {
            return ActionResponse(success: false, message: "Token expired")
        }

        // Validate CSRF token
        let isValid = tokenService.validateActionToken(
            token: request.csrfToken,
            sessionId: request.sessionId,
            action: request.action,
            timestamp: request.timestamp
        )

        guard isValid else {
            return ActionResponse(success: false, message: "Invalid CSRF token")
        }

        // Execute the state-changing action
        return executeAction(request.action, for: request.sessionId)
    }

    private func executeAction(_ action: String, for sessionId: String) -> ActionResponse {
        // Simulated action execution
        return ActionResponse(success: true, message: "Action '\(action)' executed successfully")
    }

    func generateToken(sessionId: String, action: String) -> (token: String, timestamp: UInt64) {
        let timestamp = UInt64(Date().timeIntervalSince1970)
        let token = tokenService.generateActionToken(sessionId: sessionId, action: action, timestamp: timestamp)
        return (token, timestamp)
    }
}
